# Analyze each transformation
inputs = ['fhegb', 'cgea', 'fihuxd', 'ybcdx', 'ufydiy']
outputs = ['fhegbcb', 'cgbcea', 'fiibxd', 'hfbcdx', 'gbcfhfdihf']

print("Detailed pattern analysis:")
for i in range(len(inputs)):
    inp, outp = inputs[i], outputs[i]
    print(f"\nCase {i}: '{inp}' -> '{outp}'")

    # Find where they differ
    min_len = min(len(inp), len(outp))
    diff_pos = -1
    for j in range(min_len):
        if inp[j] != outp[j]:
            diff_pos = j
            break

    if diff_pos == -1:
        if len(inp) != len(outp):
            diff_pos = min_len
            print(f"  Appended: '{outp[diff_pos:]}'")
        else:
            print("  Identical")
    else:
        print(f"  First difference at position {diff_pos}")
        if len(inp) > len(outp):
            print(f"  Removed character at position {diff_pos}")
        elif len(inp) < len(outp):
            print(f"  Added substring '{outp[diff_pos:diff_pos+len(outp)-len(inp)]}' at position {diff_pos}")
        else:
            print(f"  Replaced '{inp[diff_pos]}' with '{outp[diff_pos]}' at position {diff_pos}")

